LOCK TABLES `exercise` WRITE;
/*!40000 ALTER TABLE `exercise` DISABLE KEYS */;
INSERT INTO `exercise` VALUES (1,'Nằm sấp, hai tay rộng hơn vai, hạ thân người xuống cho đến khi ngực gần chạm sàn rồi đẩy lên.','Ngực','Hít đất',4),(2,'Nằm trên ghế phẳng, đẩy thanh đòn lên cao rồi hạ xuống chậm rãi sát ngực.','Ngực','Đẩy ngực với tạ đòn',4),(3,'Ngồi vào máy, kéo thanh đòn xuống sát ngực trên, cảm nhận sự co bóp của cơ xô và giữ lưng thẳng','Lưng','Kéo xô với máy',4),(4,'Ngồi hoặc đứng, cầm hai quả tạ đơn đẩy thẳng từ ngang vai lên trên đầu.','Vai','Đẩy vai với tạ đơn',4),(5,'Đứng thẳng, cầm tạ đơn và gập khuỷu tay để đưa tạ lên phía vai, siết chặt cơ bắp tay.','Tay trước','Cuốn tạ tay',4),(6,'Sử dụng máy kéo cáp, dùng lực tay sau đẩy thanh cầm xuống dưới cho đến khi cánh tay thẳng.','Tay sau','Kéo cáp tập tay sau',4),(7,'Đặt thanh đòn lên vai, hạ thấp hông như đang ngồi xuống ghế cho đến khi đùi song song với sàn.','Chân','Gánh tạ (Squat)',4),(8,'Ngồi vào máy đạp chân, dùng lực vùng đùi và mông đẩy bàn đạp ra xa rồi từ từ thu về.','Chân','Đạp đùi với máy',4),(9,'Nằm ngửa trên sàn, co chân, dùng cơ bụng nhấc phần vai và lưng trên lên cao rồi hạ xuống.','Bụng','Gập bụng',4),(10,'Kết hợp liên hoàn các động tác: Squat - Chống đẩy - Bật nhảy để rèn luyện sức bền toàn diện.','Toàn thân','Nhảy tổng hợp (Burpees)',4),(11,'Chống hai tay xuống xong đẩy lên','Ngực','Chống đẩy',7),(12,'Nằm ghế xong nâng tạ lên','Ngực','Nâng tạ',7),(13,'Gập bụng','Bụng','Gập bụng',7),(14,'Gập bụng khi ngồi','Bụng','Gập bụng khi ngồi',7);
/*!40000 ALTER TABLE `exercise` ENABLE KEYS */;
UNLOCK TABLES;

