INSERT INTO `fitness_class` VALUES (1,'Lớp yoga dành cho người mới bắt đầu, tập trung vào hít thở, giãn cơ và giữ thăng bằng.','Beginner','Yoga Cơ Bản','open'),(2,'Lớp yoga nâng cao với các tư thế khó, giúp tăng sức mạnh, độ dẻo dai và khả năng tập trung.','Advanced','Yoga Nâng Cao','open'),(4,'Bài tập gym toàn thân giúp đốt mỡ, tăng cơ và cải thiện thể lực tổng thể.','Intermediate','Gym Toàn Thân','draft'),(5,'Lớp cardio cường độ cao giúp giảm cân nhanh và cải thiện sức bền tim mạch.','Intermediate','Cardio Đốt Mỡ','draft'),(7,'Lớp pilates tập trung vào cơ bụng và lưng dưới, cải thiện tư thế và sự linh hoạt.','Beginner','Pilates Core','draft'),(8,'Lớp nhảy zumba sôi động theo nhạc Latin, giúp giải tỏa căng thẳng và đốt cháy calo.','Beginner','Nhảy Zumba','draft'),(9,'Lớp boxing cho người mới, học kỹ thuật đấm, né và phản xạ cơ bản.','Beginner','Boxing Cơ Bản','draft'),(10,'Võ công thâm hậu','Beginner','Luyện võ','draft'),(11,'Aerobics','Intermediate','Aerobics','draft'),(12,'Ôn tập kiến thức','Beginner','Tổng hợp kiến thức','open'),(13,'Hướng dẫn cách điều chỉnh nhịp thở','Beginner','Điều chỉnh nhịp thở','open'),(14,'Cách để có 6 múi nhanh nhất','Advanced','Gập bụng nâng cao','draft'),(15,'Giãn cơ','Beginner','Giãn cơ','waiting_approval'),(16,'Tập là có 6 múi đơn giản','Beginner','Cơ bụng sắt','waiting_approval'),(17,'Tập là có 6 múi đơn giản','Beginner','Cơ bụng thép','waiting_approval');
